import { useIntl } from 'react-intl';

import noDataAvailableIllustration from 'assets/NoDataAvailable.svg';
import { BasicContainer } from 'components';

import { StyledErrorStateContainer } from './DrillDownErrorState.styles';

const DEFAULT_DESCRIPTION_ID = 'ValueCreation.drillDownErrorState.description';
const DEFAULT_TEST_ID = 'drill-down-error-state';

interface DrillDownErrorStateProps {
  dataTestId?: string;
  descriptionId?: string;
}

export const DrillDownErrorState: React.FC<DrillDownErrorStateProps> = ({
  dataTestId = DEFAULT_TEST_ID,
  descriptionId = DEFAULT_DESCRIPTION_ID,
}) => {
  const { formatMessage } = useIntl();

  return (
    <BasicContainer fullWidth={true} data-testid={dataTestId}>
      <StyledErrorStateContainer>
        <img
          src={noDataAvailableIllustration}
          alt=""
          aria-hidden="true"
          data-testid={`${dataTestId}-illustration`}
        />
        <p data-testid={`${dataTestId}-description`}>
          {formatMessage({ id: descriptionId })}
        </p>
      </StyledErrorStateContainer>
    </BasicContainer>
  );
};
